def safe_int(campo: str, valor: str):
    texto = valor.strip()
    if texto == "":
        return False, None, f"ERROR en '{campo}': valor vacío"
    try:
        return True, int(texto), None
    except ValueError:
        return False, None, f"ERROR en '{campo}': no se pudo convertir {valor!r} a int"

def pipeline(edad_txt, anios_txt):
    raw = {"edad": edad_txt, "anios_cliente": anios_txt}
    clean = {}
    errors = []
    for campo, valor in raw.items():
        ok, n, err = safe_int(campo, valor)
        clean[campo] = n if ok else None
        if err is not None:
            errors.append(err)
    return {"raw": raw, "clean": clean, "errors": errors}

def parse_monto(texto):
    raw = texto
    limpio = texto.strip()
    if limpio == "":
        return False, None, f"ERROR en 'monto': valor vacío (raw={raw!r})"
    try:
        monto = Decimal(limpio).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
        return True, monto, None
    except InvalidOperation:
        return False, None, f"ERROR en 'monto': no se pudo convertir {raw!r} a Decimal"

def parse_nombres(valor):
    errors = []
    limpio = valor.strip()
    if limpio == "":
        errors.append(f"ERROR en 'nombres': vacío (raw={valor!r})")
        limpio = None
    return {"nombres_raw": valor, "nombres": limpio, "errors": errors}
